180: static long card_ioctl(struct file *file, unsigned int cmd,
181:                          unsigned long arg) {
182:     void __user *argp = (void __user *)arg;
183:     int __user *p = argp;
184: 
185:     // check correct magic
186:     // if (_IOC_TYPE(cmd) != SNIOC_MAGIC)
187:     //   return -ENOTTY;
188: 
189:     switch (cmd) {
190:     // Alloc physically contiguous memory
191:     case 0x1: {
192:         struct card_alloc_arg arg;
193:         phys_addr_t result_phy = 0;
194:         if (copy_from_user(&arg, p, sizeof(struct card_alloc_arg)))
195:             return -EFAULT;
196:         arg.result_virt_addr = kmalloc(arg.size, GFP_ATOMIC);
197:         if (arg.result_virt_addr < 0) {
198:             return arg.result_virt_addr;
199:         }
200:         arg.result_phys_addr = virt_to_phys(arg.result_virt_addr);
201:         copy_to_user(p, &arg, sizeof(struct card_alloc_arg));
202: 
203:         return arg.result_virt_addr;
204:     }
205:     }
206:     return 0;
207: }
